static unsafe int SumPinned(ReadOnlySpan<int> data)
{
    fixed (int* p = data)
    {
        var total = 0;
        for (var i = 0; i < data.Length; i++)
        {
            total += p[i];
        }
        return total;
    }
}

static int SumSafe(ReadOnlySpan<int> data)
{
    var total = 0;
    foreach (var n in data) total += n;
    return total;
}

unsafe static extern void NativeHash(byte* data, int length, byte* digest);

static unsafe void Hash(ReadOnlySpan<byte> payload, Span<byte> digest)
{
    fixed (byte* p = payload)
    fixed (byte* d = digest)
    {
        NativeHash(p, payload.Length, d);
    }
}
